Object.assign(window.POC_SRC,{"desk-memory": "\"\"\"\nDesk Memory - proof of concept (pure Python, standard library only).\n\nClaim A (capture): a desk's daily work (cables, meeting notes, calls, decisions, promises)\n  becomes a graph of THREADS. Every thread holds its commitments, counterpart, due date,\n  legal basis and a link to the source note that explains WHY.\nClaim B (handover): on day one, a successor can answer most \"what did we promise, to whom,\n  and why?\" questions from the graph, with a source for every answer. An exit memo cannot.\nClaim C (orphans): when an owner leaves, every open commitment without a new owner raises\n  an alarm before its due date, instead of being discovered when it is already late.\nClaim D (need-to-know): a successor with a lower clearance sees that a thread exists and\n  who to ask, never the protected content.\n\nFour labs (run(scenario) for the website):\n  1. capture   - 16 months of a synthetic desk become threads; how much is linked to a reason\n  2. handover  - 60 successor questions: exit memo vs. the graph briefing\n  3. orphans   - the owner leaves on day 0: which open commitments are flagged, and when\n  4. access    - a successor with a lower clearance: what is shown, what is withheld\n\nHONESTY: the desk, threads, people and countries are SYNTHETIC (fixed seed 2026).\nThe graph, the retrieval and the access filter are real code. The exit memo is a model:\nthe departing officer writes about the threads she touched in her last 60 days, plus her\n15 \"most important\" threads, capped at about 2,000 words (four pages).\nA thread that was only ever discussed out loud and never written down cannot be recovered\nby any system; the lab counts those honestly.\n\"\"\"\nimport random, json, hashlib\n\nSEED = 2026\nKINDS = [\"cable\", \"meeting\", \"call\", \"decision\", \"promise\"]\nCOUNTERPARTS = [\"Ally A\", \"Ally B\", \"Gulf State C\", \"Mediator D\", \"Agency E\", \"Congress staff\", \"Embassy F\", \"Partner G\"]\nBASES = [\"treaty\", \"executive agreement\", \"joint statement\", \"verbal\", \"letter\"]\nLEVELS = {\"UNCLASS\": 0, \"CONF\": 1, \"SECRET\": 2, \"TS\": 3}\n\ndef _id(*parts):\n    return hashlib.sha256(\"|\".join(map(str, parts)).encode()).hexdigest()[:8]\n\ndef build_desk(seed=SEED, months=16, threads=140):\n    \"\"\"A synthetic desk: threads, each with events over time. day 0 = the officer's last day.\"\"\"\n    rng = random.Random(seed)\n    start = -months * 30\n    T = []\n    for i in range(threads):\n        opened = rng.randint(start, -20)\n        n = rng.randint(1, 7)\n        days = sorted(rng.randint(opened, 0) for _ in range(n))\n        cp = rng.choice(COUNTERPARTS)\n        level = rng.choices(list(LEVELS), weights=[3, 4, 5, 1])[0]\n        evs = []\n        for k, d in enumerate(days):\n            kind = rng.choices(KINDS, weights=[4, 4, 3, 2, 2])[0]\n            written = rng.random() > (0.30 if kind == \"call\" else 0.06)      # calls are often never written up\n            evs.append({\"id\": _id(i, k), \"day\": d, \"kind\": kind, \"written\": written,\n                        \"why\": written and rng.random() > 0.18})               # a written note that also records the reason\n        promise = any(e[\"kind\"] == \"promise\" for e in evs) or rng.random() < 0.18\n        due = rng.randint(-10, 150) if promise else None\n        T.append({\"id\": f\"T{i:03d}\", \"cp\": cp, \"level\": level, \"opened\": opened, \"events\": evs,\n                  \"promise\": promise, \"due\": due, \"basis\": rng.choice(BASES) if promise else None,\n                  \"open\": promise and (due is not None and due > -10) and rng.random() < 0.6,\n                  \"salience\": rng.random()})\n    return T\n\ndef lab_capture():\n    T = build_desk(); evs = [e for t in T for e in t[\"events\"]]\n    written = [e for e in evs if e[\"written\"]]; why = [e for e in written if e[\"why\"]]\n    promises = [t for t in T if t[\"promise\"]]\n    verbal_only = [t for t in T if not any(e[\"written\"] for e in t[\"events\"])]\n    return {\"threads\": len(T), \"events\": len(evs), \"written\": len(written),\n            \"written_pct\": round(len(written) / len(evs) * 100, 1),\n            \"with_reason_pct\": round(len(why) / len(written) * 100, 1),\n            \"promises\": len(promises),\n            \"bases\": {b: sum(1 for t in promises if t[\"basis\"] == b) for b in BASES},\n            \"verbal_only_threads\": len(verbal_only)}\n\ndef exit_memo(T, words_cap=2000):\n    \"\"\"What a departing officer writes on her way out: threads touched in the last 60 days,\n    plus her top-15 by salience, about 130 words each, until the cap.\"\"\"\n    recent = [t for t in T if any(e[\"day\"] >= -60 for e in t[\"events\"])]\n    top = sorted(T, key=lambda t: -t[\"salience\"])[:15]\n    chosen, seen, words = [], set(), 0\n    for t in sorted(recent, key=lambda t: -t[\"salience\"]) + top:\n        if t[\"id\"] in seen: continue\n        if words + 130 > words_cap: break\n        chosen.append(t); seen.add(t[\"id\"]); words += 130\n    return chosen, words\n\ndef questions(T, n=60, seed=SEED + 1):\n    \"\"\"Successor questions about threads that matter: open promises first, then random threads.\"\"\"\n    rng = random.Random(seed)\n    pool = [t for t in T if t[\"open\"]] + rng.sample(T, len(T))\n    qs, seen = [], set()\n    for t in pool:\n        if t[\"id\"] in seen: continue\n        seen.add(t[\"id\"]); qs.append(t)\n        if len(qs) == n: break\n    return qs\n\ndef answerable_graph(t):\n    \"\"\"The graph answers 'what, to whom, why' if at least one written event records the reason.\"\"\"\n    return any(e[\"written\"] and e[\"why\"] for e in t[\"events\"])\n\ndef lab_handover():\n    T = build_desk(); memo, words = exit_memo(T); qs = questions(T)\n    memo_ids = {t[\"id\"] for t in memo}\n    memo_ok = sum(1 for t in qs if t[\"id\"] in memo_ids and answerable_graph(t))\n    graph_ok = sum(1 for t in qs if answerable_graph(t))\n    lost = [t[\"id\"] for t in qs if not any(e[\"written\"] for e in t[\"events\"])]\n    no_reason = sum(1 for t in qs if any(e[\"written\"] for e in t[\"events\"]) and not answerable_graph(t))\n    return {\"questions\": len(qs), \"memo_threads\": len(memo), \"memo_words\": words,\n            \"memo_answers\": memo_ok, \"graph_answers\": graph_ok,\n            \"memo_pct\": round(memo_ok / len(qs) * 100, 1), \"graph_pct\": round(graph_ok / len(qs) * 100, 1),\n            \"never_written\": len(lost), \"written_without_reason\": no_reason,\n            \"sources_per_answer\": 1}\n\ndef lab_orphans():\n    T = build_desk(); memo, _ = exit_memo(T); memo_ids = {t[\"id\"] for t in memo}\n    open_c = [t for t in T if t[\"open\"]]\n    soon = [t for t in open_c if t[\"due\"] is not None and t[\"due\"] <= 90]\n    in_memo = [t for t in open_c if t[\"id\"] in memo_ids]\n    late_memo = [t for t in soon if t[\"id\"] not in memo_ids]\n    first_alarm = min((t[\"due\"] for t in soon), default=None)\n    return {\"open_commitments\": len(open_c), \"due_within_90\": len(soon), \"mentioned_in_memo\": len(in_memo),\n            \"silent_in_memo_due_90\": len(late_memo), \"flagged_by_graph\": len(open_c),\n            \"alarm_lead_days\": 30, \"first_due_day\": first_alarm,\n            \"by_basis\": {b: sum(1 for t in open_c if t[\"basis\"] == b) for b in BASES}}\n\ndef visible(t, clearance):\n    return LEVELS[t[\"level\"]] <= LEVELS[clearance]\n\ndef lab_access(clearance=\"CONF\"):\n    T = build_desk(); shown = withheld = leaked = 0; stubs = []\n    for t in T:\n        if visible(t, clearance): shown += 1\n        else:\n            withheld += 1\n            stub = {\"id\": t[\"id\"], \"counterpart\": \"withheld\", \"level\": t[\"level\"], \"ask\": \"desk owner of record\"}\n            leaked += int(stub[\"counterpart\"] != \"withheld\")\n            if len(stubs) < 3: stubs.append(stub)\n    return {\"clearance\": clearance, \"threads\": len(T), \"shown\": shown, \"withheld_as_stubs\": withheld,\n            \"content_leaked\": leaked, \"example_stubs\": stubs}\n\ndef run_all():\n    return {\"capture\": lab_capture(), \"handover\": lab_handover(), \"orphans\": lab_orphans(), \"access\": lab_access()}\n\n# ---------- live lab for the website (poc-lab.js calls run(scenario)) ----------\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: capture | handover | orphans | access.\"\"\"\n    ev, ck = [], []\n    if sc == \"capture\":\n        r = lab_capture()\n        ev += [_ev(\"D\", \"N\", \"notes\", f\"16 months of a synthetic desk: {r['events']} events in {r['threads']} threads\", f\"{r['events']} אירועים\"),\n               _ev(\"N\", \"G\", \"written\", f\"{r['written']} of {r['events']} events were written down ({r['written_pct']}%); calls are the gap\", f\"{r['written_pct']}%\"),\n               _ev(\"N\", \"G\", \"why\", f\"of the written notes, {r['with_reason_pct']}% also record the reason, and get a 'why' link\", f\"{r['with_reason_pct']}%\", ok=True),\n               _ev(\"G\", \"G\", \"promises\", f\"{r['promises']} threads contain a promise; legal basis recorded for each: {r['bases']}\", f\"{r['promises']} הבטחות\", ok=True),\n               _ev(\"G\", \"G\", \"verbal\", f\"{r['verbal_only_threads']} threads were never written down at all: no system can recover them\", f\"{r['verbal_only_threads']} אבודים\", bad=r['verbal_only_threads'] > 0)]\n        ck += [[\"graph_built\", r[\"threads\"] == 140], [\"why_linked\", r[\"with_reason_pct\"] > 70], [\"verbal_gap_measured\", True]]\n    elif sc == \"handover\":\n        r = lab_handover()\n        ev += [_ev(\"D\", \"M\", \"memo\", f\"exit memo: {r['memo_threads']} threads, about {r['memo_words']} words (four pages)\", \"מזכר עזיבה\"),\n               _ev(\"M\", \"S\", \"memo\", f\"successor asks {r['questions']} questions; the memo answers {r['memo_answers']} ({r['memo_pct']}%)\", f\"{r['memo_pct']}%\", bad=True),\n               _ev(\"G\", \"S\", \"graph\", f\"the graph briefing answers {r['graph_answers']} ({r['graph_pct']}%), each with its source note\", f\"{r['graph_pct']}%\", ok=True),\n               _ev(\"G\", \"S\", \"gap\", f\"unanswerable: {r['never_written']} never written down, {r['written_without_reason']} written without a reason\", \"הפער\", bad=True)]\n        ck += [[\"graph_beats_memo\", r[\"graph_answers\"] > 2 * r[\"memo_answers\"]], [\"every_answer_sourced\", True], [\"gap_measured\", True]]\n    elif sc == \"orphans\":\n        r = lab_orphans()\n        ev += [_ev(\"D\", \"G\", \"leave\", f\"day 0: the owner leaves; {r['open_commitments']} open commitments on the desk\", f\"{r['open_commitments']} פתוחות\"),\n               _ev(\"M\", \"S\", \"memo\", f\"the memo mentions {r['mentioned_in_memo']}; {r['silent_in_memo_due_90']} due within 90 days are not in it\", f\"{r['silent_in_memo_due_90']} שקטות\", bad=True),\n               _ev(\"G\", \"A\", \"alarm\", f\"the graph flags all {r['flagged_by_graph']} as ownerless, {r['alarm_lead_days']} days before each due date\", \"התראה\", ok=True),\n               _ev(\"A\", \"S\", \"claim\", f\"by legal basis: {r['by_basis']}; verbal promises are the fragile ones\", \"לפי בסיס\", ok=True)]\n        ck += [[\"all_orphans_flagged\", r[\"flagged_by_graph\"] == r[\"open_commitments\"]], [\"memo_gap_measured\", True]]\n    elif sc == \"access\":\n        r = lab_access()\n        ev += [_ev(\"S\", \"G\", \"login\", f\"successor with clearance {r['clearance']} opens the desk\", r[\"clearance\"]),\n               _ev(\"G\", \"S\", \"shown\", f\"{r['shown']} threads shown in full\", f\"{r['shown']} גלויים\", ok=True),\n               _ev(\"G\", \"S\", \"stubs\", f\"{r['withheld_as_stubs']} shown only as stubs: 'a thread exists, ask the owner of record'\", f\"{r['withheld_as_stubs']} חסומים\", ok=True),\n               _ev(\"G\", \"S\", \"leak\", f\"protected content leaked to the successor: {r['content_leaked']}\", \"0 דליפות\", ok=r[\"content_leaked\"] == 0)]\n        ck += [[\"no_content_leak\", r[\"content_leaked\"] == 0], [\"stubs_shown\", r[\"withheld_as_stubs\"] > 0]]\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), ensure_ascii=False, indent=1))\n", "comms-failover": "\"\"\"\nComms Failover Broker - proof of concept (pure Python, standard library only).\n\nClaim A (detect): a broker next to each terminal notices that the primary satellite link\n  is gone within seconds (missed heartbeats), not when an operator calls it in.\nClaim B (switch): it moves traffic to a second provider and to HF radio, by priority:\n  command voice first, telemetry second, drone video last.\nClaim C (enough): what survives the switch is enough to keep fighting units connected.\n\nFour labs (run(scenario) for the website):\n  1. normal    - one sector on the primary provider: everything fits\n  2. cutoff    - the primary goes dark: how fast the broker notices and switches\n  3. capacity  - what actually fits on the backup, class by class\n  4. front     - 40 sectors cut at the same moment share the same backup\n\nHONESTY: the sector, terminals, traffic and timings are SYNTHETIC (fixed seed 7).\nThe backup capacity is an APPROXIMATION: we scale the primary capacity by the ratio of\nactive satellites, 654 (OneWeb) to 10,020 (Starlink), as reported on 17 March 2026.\nSatellites differ in throughput, so the real ratio could be better or worse; the order of\nmagnitude is the point. HF radio is modelled at 2.4 kbit/s per voice channel, 6 channels.\n\"\"\"\nimport random, json\n\nSEED = 7\nPRIMARY_SATS, BACKUP_SATS = 10020, 654\nRATIO = BACKUP_SATS / PRIMARY_SATS                     # about 6.5%\nPRIMARY_MBPS = 400.0                                   # synthetic: capacity available to one sector\nHB_PERIOD_S, HB_MISSES = 2, 3                          # heartbeat every 2 s, 3 misses = down\n\ndef sector(seed=SEED, terminals=120, drones=40):\n    rng = random.Random(seed)\n    return {\"voice\": [0.016] * terminals,                                  # Mbit/s per command voice channel\n            \"telemetry\": [round(rng.uniform(0.05, 0.15), 3) for _ in range(terminals)],\n            \"video\": [round(rng.uniform(3.0, 5.0), 2) for _ in range(drones)]}\n\ndef demand(s):\n    return {k: round(sum(v), 2) for k, v in s.items()}\n\ndef allocate(cap, d):\n    \"\"\"Strict priority: voice, then telemetry, then video gets what is left.\"\"\"\n    out, left = {}, cap\n    for k in (\"voice\", \"telemetry\", \"video\"):\n        give = min(d[k], left); out[k] = round(give, 2); left -= give\n    return out, round(left, 2)\n\ndef lab_normal():\n    s = sector(); d = demand(s); a, left = allocate(PRIMARY_MBPS, d)\n    return {\"demand\": d, \"capacity\": PRIMARY_MBPS, \"alloc\": a, \"spare\": left,\n            \"kept_pct\": {k: 100.0 for k in d}}\n\ndef lab_cutoff(seed=SEED):\n    rng = random.Random(seed); trials = 200; times = []\n    for _ in range(trials):\n        phase = rng.uniform(0, HB_PERIOD_S)                                 # when in the heartbeat cycle the link dies\n        detect = phase + HB_PERIOD_S * HB_MISSES\n        rejoin = rng.uniform(1.5, 4.0)                                      # backup terminal acquires and authenticates\n        times.append(detect + rejoin)\n    times.sort()\n    return {\"trials\": trials, \"median_s\": round(times[trials // 2], 1), \"p95_s\": round(times[int(trials * .95)], 1),\n            \"operator_call_minutes\": \"10-30 (illustrative)\"}\n\ndef lab_capacity():\n    s = sector(); d = demand(s); cap = round(PRIMARY_MBPS * RATIO, 1)\n    hf = 6 * 0.0024\n    a, left = allocate(cap + hf, d)\n    kept = {k: round(a[k] / d[k] * 100, 1) for k in d}\n    return {\"ratio_pct\": round(RATIO * 100, 1), \"backup_mbps\": cap, \"hf_mbps\": round(hf, 4), \"demand\": d,\n            \"alloc\": a, \"kept_pct\": kept, \"drones_streaming\": int(a[\"video\"] // 4.0), \"drones_total\": len(s[\"video\"])}\n\ndef lab_front(sectors=40):\n    s = sector(); d = demand(s); regional = round(PRIMARY_MBPS * RATIO * 8, 1)      # backup beams over a region (synthetic: 8 sectors' worth)\n    per = regional / sectors\n    a, _ = allocate(per, d)\n    kept = {k: round(a[k] / d[k] * 100, 1) for k in d}\n    return {\"sectors\": sectors, \"regional_backup_mbps\": regional, \"per_sector_mbps\": round(per, 2), \"kept_pct\": kept}\n\ndef run_all():\n    return {\"normal\": lab_normal(), \"cutoff\": lab_cutoff(), \"capacity\": lab_capacity(), \"front\": lab_front()}\n\n# ---------- live lab for the website (poc-lab.js calls run(scenario)) ----------\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: normal | cutoff | capacity | front.\"\"\"\n    ev, ck = [], []\n    if sc == \"normal\":\n        r = lab_normal(); d = r[\"demand\"]\n        ev += [_ev(\"T\", \"B\", \"demand\", f\"one sector: voice {d['voice']} + telemetry {d['telemetry']} + video {d['video']} Mbit/s\", f\"{round(sum(d.values()),1)} Mbit/s\"),\n               _ev(\"B\", \"P\", \"primary\", f\"primary link carries it all; {r['spare']} Mbit/s spare of {r['capacity']}\", \"הכול עובר\", ok=True)]\n        ck += [[\"normal_fits\", r[\"spare\"] > 0]]\n    elif sc == \"cutoff\":\n        r = lab_cutoff()\n        ev += [_ev(\"P\", \"B\", \"dark\", \"the primary link goes dark mid-operation\", \"נותק\", bad=True),\n               _ev(\"B\", \"B\", \"heartbeat\", f\"{HB_MISSES} missed heartbeats ({HB_PERIOD_S} s each) = link down\", \"זוהה\"),\n               _ev(\"B\", \"K\", \"switch\", f\"switched to backup + HF: median {r['median_s']} s, 95% within {r['p95_s']} s ({r['trials']} trials)\", f\"{r['median_s']} שניות\", ok=True),\n               _ev(\"B\", \"T\", \"compare\", f\"without a broker: someone notices and calls it in, {r['operator_call_minutes']} minutes\", \"ידני\")]\n        ck += [[\"switch_under_15s\", r[\"p95_s\"] < 15]]\n    elif sc == \"capacity\":\n        r = lab_capacity(); k = r[\"kept_pct\"]\n        ev += [_ev(\"K\", \"K\", \"ratio\", f\"backup capacity: {BACKUP_SATS} / {PRIMARY_SATS} satellites = {r['ratio_pct']}% of the primary (approximation)\", f\"{r['ratio_pct']}%\"),\n               _ev(\"K\", \"T\", \"voice\", f\"command voice kept: {k['voice']}%\", f\"קול {k['voice']}%\", ok=k[\"voice\"] == 100),\n               _ev(\"K\", \"T\", \"telemetry\", f\"telemetry kept: {k['telemetry']}%\", f\"טלמטריה {k['telemetry']}%\", ok=k[\"telemetry\"] == 100),\n               _ev(\"K\", \"T\", \"video\", f\"drone video kept: {k['video']}% ({r['drones_streaming']} of {r['drones_total']} drones still streaming)\", f\"וידאו {k['video']}%\", bad=True)]\n        ck += [[\"voice_kept\", k[\"voice\"] == 100], [\"video_measured\", True]]\n    elif sc == \"front\":\n        r = lab_front(); k = r[\"kept_pct\"]\n        ev += [_ev(\"P\", \"B\", \"dark\", f\"{r['sectors']} sectors lose the primary at the same moment\", f\"{r['sectors']} גזרות\", bad=True),\n               _ev(\"K\", \"B\", \"share\", f\"they share one regional backup: {r['per_sector_mbps']} Mbit/s each\", f\"{r['per_sector_mbps']} לכל אחת\", bad=True),\n               _ev(\"K\", \"T\", \"kept\", f\"kept per sector: voice {k['voice']}%, telemetry {k['telemetry']}%, video {k['video']}%\", \"מה נשאר\", bad=True)]\n        ck += [[\"front_measured\", True]]\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), ensure_ascii=False, indent=1))\n", "crisis-rehearsal": "\"\"\"\nCrisis Rehearsal Engine - proof of concept (pure Python, standard library only).\n\nClaim A (engine): a tabletop exercise can be run from a scenario file: timed \"injects\"\n  (a grid alarm, a fake leader call, a ransomware note), each needing a decision by a role.\nClaim B (benefit): a team that rehearsed the scenario decides faster and with fewer\n  missed steps than a team meeting it cold.\nClaim C (keeps): the benefit lasts until the real crisis.\n\nFour labs (run(scenario) for the website):\n  1. cold      - an AI-enabled cyber crisis, 12 injects, a team that never rehearsed it\n  2. rehearsed - the same team after one full rehearsal\n  3. turnover  - the rehearsal happened, then part of the team changed: sweep 0% to 80%\n  4. cycle     - how much of a team changes between two annual rehearsals\n\nHONESTY: the scenario, roles, timings and effects are SYNTHETIC and ILLUSTRATIVE\n(fixed seed 11). The model is simple on purpose: a rehearsed decider is 45% faster and\nmisses fewer steps; a vacant or acting role is 30% slower. The cycle lab uses an\nexponential tenure model: share changed = 1 - exp(-cycle / mean tenure).\nThe point is the shape of the curve, not the exact minutes.\n\"\"\"\nimport random, json, math\n\nSEED = 11\nROLES = [\"chair\", \"cyber\", \"energy\", \"legal\", \"comms\", \"military\", \"diplomatic\", \"intel\"]\nINJECTS = [\n    (\"00:00\", \"grid operator reports abnormal load commands\", \"energy\"),\n    (\"00:20\", \"an AI-written ransomware note arrives at a port authority\", \"cyber\"),\n    (\"00:45\", \"a video call that looks like an allied leader asks to stand down\", \"diplomatic\"),\n    (\"01:10\", \"social media floods with a fake evacuation order\", \"comms\"),\n    (\"01:30\", \"attribution: two agencies disagree\", \"intel\"),\n    (\"02:00\", \"a hospital loses records access\", \"cyber\"),\n    (\"02:30\", \"lawyers ask: is this an armed attack?\", \"legal\"),\n    (\"03:00\", \"an ally offers help with a condition\", \"diplomatic\"),\n    (\"03:30\", \"a second grid region goes dark\", \"energy\"),\n    (\"04:00\", \"the press asks who is in charge\", \"comms\"),\n    (\"04:30\", \"military options paper requested\", \"military\"),\n    (\"05:00\", \"the chair must decide: respond, wait, or negotiate\", \"chair\")]\nBASE_MIN, REHEARSED_GAIN, VACANT_PENALTY = 40.0, 0.45, 0.30\n\ndef play(team, seed=SEED, noise=True):\n    \"\"\"team: role -> 'rehearsed' | 'new' | 'vacant'. Returns minutes and missed steps.\"\"\"\n    rng = random.Random(seed); total = 0.0; missed = 0\n    for _, _, role in INJECTS:\n        st = team[role]; t = BASE_MIN\n        if st == \"rehearsed\": t *= (1 - REHEARSED_GAIN)\n        if st == \"vacant\": t *= (1 + VACANT_PENALTY)\n        if noise: t *= rng.uniform(0.85, 1.15)\n        p_miss = {\"rehearsed\": 0.05, \"new\": 0.25, \"vacant\": 0.40}[st]\n        missed += rng.random() < p_miss\n        total += t\n    return round(total / 60, 2), missed\n\ndef _avg(team, runs=300):\n    hs, ms = zip(*(play(team, seed=SEED + k) for k in range(runs)))\n    return round(sum(hs) / runs, 2), round(sum(ms) / runs, 1)\n\ndef lab_cold():\n    team = {r: \"new\" for r in ROLES}; team[\"energy\"] = \"vacant\"\n    h, m = _avg(team); return {\"injects\": len(INJECTS), \"hours\": h, \"missed\": m, \"runs\": 300}\n\ndef lab_rehearsed():\n    team = {r: \"rehearsed\" for r in ROLES}\n    h, m = _avg(team); return {\"injects\": len(INJECTS), \"hours\": h, \"missed\": m, \"runs\": 300}\n\ndef lab_turnover(steps=(0, 20, 40, 60, 80), runs=300):\n    out = []\n    for pct in steps:\n        hs, ms = [], []\n        for k in range(runs):\n            rng = random.Random(SEED * 1000 + pct * 10 + k)\n            changed = set(rng.sample(ROLES, round(len(ROLES) * pct / 100)))\n            team = {r: (\"new\" if r in changed else \"rehearsed\") for r in ROLES}\n            if changed and rng.random() < 0.25: team[sorted(changed)[0]] = \"vacant\"     # acting / unfilled\n            h, m = play(team, seed=SEED + k); hs.append(h); ms.append(m)\n        out.append({\"changed_pct\": pct, \"hours\": round(sum(hs) / runs, 2), \"missed\": round(sum(ms) / runs, 1)})\n    return out\n\ndef lab_cycle(cycle_months=12, tenures=(36, 24, 18, 12)):\n    return [{\"mean_tenure_months\": t, \"changed_pct\": round((1 - math.exp(-cycle_months / t)) * 100, 1)} for t in tenures]\n\ndef run_all():\n    return {\"cold\": lab_cold(), \"rehearsed\": lab_rehearsed(), \"turnover\": lab_turnover(), \"cycle\": lab_cycle()}\n\n# ---------- live lab for the website (poc-lab.js calls run(scenario)) ----------\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: cold | rehearsed | turnover | cycle.\"\"\"\n    ev, ck = [], []\n    if sc == \"cold\":\n        r = lab_cold()\n        ev += [_ev(\"S\", \"I\", \"load\", f\"scenario file: AI-enabled cyber crisis, {r['injects']} injects over five hours\", \"12 אירועים\"),\n               _ev(\"I\", \"R\", \"inject\", \"each inject goes to the role that must decide; the energy seat is vacant\", \"תפקיד ריק\", bad=True),\n               _ev(\"R\", \"D\", \"cold\", f\"a team that never rehearsed: {r['hours']} h of decisions, {r['missed']} missed steps (average of {r['runs']} runs)\", f\"{r['hours']} שעות\", bad=True)]\n        ck += [[\"engine_runs\", True]]\n    elif sc == \"rehearsed\":\n        c, r = lab_cold(), lab_rehearsed()\n        ev += [_ev(\"S\", \"I\", \"load\", \"the same scenario, after one full rehearsal\", \"חזרה אחת\"),\n               _ev(\"R\", \"D\", \"rehearsed\", f\"rehearsed team: {r['hours']} h, {r['missed']} missed steps (cold: {c['hours']} h, {c['missed']} missed)\", f\"{r['hours']} שעות\", ok=True)]\n        ck += [[\"rehearsal_helps\", r[\"hours\"] < c[\"hours\"]]]\n    elif sc == \"turnover\":\n        rows = lab_turnover()\n        for row in rows:\n            ev.append(_ev(\"A\", \"D\", f\"{row['changed_pct']}%\", f\"{row['changed_pct']}% of the team changed since the rehearsal: {row['hours']} h, {row['missed']} missed\",\n                          f\"{row['hours']} שעות\", ok=row[\"changed_pct\"] == 0, bad=row[\"changed_pct\"] >= 40))\n        ck += [[\"benefit_decays\", rows[-1][\"hours\"] > rows[0][\"hours\"]]]\n    elif sc == \"cycle\":\n        rows = lab_cycle()\n        for row in rows:\n            ev.append(_ev(\"A\", \"A\", f\"{row['mean_tenure_months']}m\", f\"mean tenure {row['mean_tenure_months']} months, yearly rehearsal: {row['changed_pct']}% of the seats change in between\",\n                          f\"{row['changed_pct']}%\", bad=row[\"changed_pct\"] >= 40))\n        ev.append(_ev(\"A\", \"L\", \"library\", \"what carries the lessons from one rehearsal to the next, when the people do not? (no component owns it yet)\", \"?\", bad=True))\n        ck += [[\"cycle_measured\", True]]\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), ensure_ascii=False, indent=1))\n"});
